# ---------------------------------------------------------------------------
# 基础工具
# ---------------------------------------------------------------------------
have() { command -v "$1" >/dev/null 2>&1; }

# Keep nested commands in the scan's process group when the watchdog is active.
bounded_command() (
    local limiter=$1 seconds=$2 limit=$3 output size rc=0 merge=0
    local -a opts=(-k 1s)
    shift 3
    if [[ $1 == --merge-stderr ]]; then merge=1; shift; fi
    if [[ -n ${SCAN_WORK:-} ]]; then opts+=(--foreground); fi
    export LC_ALL=C
    output=$(mktemp "${SCAN_WORK:-${WORK:-${TMPDIR:-/tmp}}}/command.XXXXXX") || return 1
    trap 'rm -f -- "$output"' EXIT
    set -o pipefail
    {
        if (( merge )); then exec 2>&1; fi
        exec "$limiter" "${opts[@]}" "$seconds" "$@" </dev/null
    } | head -c "$((limit + 1))" > "$output" || rc=$?
    size=$(wc -c < "$output") || return 1
    (( size <= limit )) || return 125
    (( rc == 0 )) || return "$rc"
    cat -- "$output"
)

lower() { printf '%s' "${1:-}" | tr '[:upper:]' '[:lower:]'; }

trim() { printf '%s' "${1:-}" | sed 's/^[[:space:]]*//; s/[[:space:]]*$//'; }

die() { printf '错误: %s\n' "$*" >&2; exit 2; }

note_progress() { [ "$QUIET" -eq 1 ] || printf '[i] %s\n' "$*" >&2; }

# 追加一条采集提示（写文件，跨子 shell 安全）
warn() {
    printf '%s\n' "$*" >> "$WARN_FILE" || die "写入巡检提示失败"
}

# 把可能破坏 TSV 的字符压平
san_field() {
    printf '%s' "${1:-}" | LC_ALL=C tr '\t\n' '  ' | LC_ALL=C tr -d '\037'
}

# 解析符号链接（相对目标也能处理）
resolve_symlinks() {
    local p=${1:-} t d i=0
    while [ -L "$p" ]; do
        i=$((i + 1))
        [ "$i" -gt 20 ] && break
        t=$(readlink "$p" 2>/dev/null) || break
        [ -n "$t" ] || break
        case $t in
            /*) p=$t ;;
            *) d=$(dirname "$p"); p="$d/$t" ;;
        esac
    done
    printf '%s' "$p"
}

# 规范化父目录（不解析最后一段，用于保留可能不存在的路径）
real_path() {
    local p=${1:-} d b
    [ -n "$p" ] || { printf ''; return; }
    b=${p##*/}
    d=${p%/*}
    [ -n "$d" ] || d=/
    if cd "$d" 2>/dev/null; then
        printf '%s/%s' "$(pwd -P)" "$b"
    else
        printf '%s' "$p"
    fi
}

# ---------------------------------------------------------------------------
# 版本号比较（纯数字元组，右补 0）
#   vcmp A B -> -1 / 0 / 1
# ---------------------------------------------------------------------------
vcmp() {
    awk -v a="${1:-0}" -v b="${2:-0}" 'BEGIN{
        na = split(a, A, ".")
        nb = split(b, B, ".")
        n = (na > nb) ? na : nb
        for (i = 1; i <= n; i++) {
            pa = (i <= na) ? (A[i] + 0) : 0
            pb = (i <= nb) ? (B[i] + 0) : 0
            if (pa > pb) { print 1; exit }
            if (pa < pb) { print -1; exit }
        }
        print 0
    }'
}
vgt() { [ "$(vcmp "$1" "$2")" = 1 ]; }
vge() { [ "$(vcmp "$1" "$2")" != -1 ]; }
vlt() { [ "$(vcmp "$1" "$2")" = -1 ]; }
vle() { [ "$(vcmp "$1" "$2")" != 1 ]; }

# ---------------------------------------------------------------------------
# CPU 条件
#   cpu_from_text : stdin 为 cpuinfo 文本，输出 "state with without procs"
# ---------------------------------------------------------------------------
cpu_from_text() {
    awk '
    {
        line = $0
        sub(/\r$/, "", line)
        if (line ~ /^[ \t]*processor[ \t]*:/) {
            procs++
        } else if (line ~ /^[ \t]*flags[ \t]*:/) {
            sub(/^[^:]*:/, "", line)
            n = split(line, a, /[ \t]+/)
            has_f = 0; has_bw = 0; has_vbmi = 0; has_bmi2 = 0
            for (i = 1; i <= n; i++) {
                f = a[i]
                if (f == "avx512f") has_f = 1
                else if (f == "avx512bw") has_bw = 1
                else if (f == "avx512vbmi" || f == "avx512_vbmi") has_vbmi = 1
                else if (f == "bmi2") has_bmi2 = 1
            }
            if (has_f && has_bw && has_vbmi && has_bmi2) withf++; else without++
            flags++
        }
    }
    END {
        if (flags == 0 || procs == 0)            print "unknown 0 0 " procs + 0
        else if (flags != procs)                 print "unknown " withf + 0 " " without + 0 " " procs + 0
        else if (withf > 0 && without > 0)       print "mixed " withf + 0 " " without + 0 " " procs + 0
        else if (withf > 0)                      print "present " withf + 0 " " without + 0 " " procs + 0
        else                                     print "absent " withf + 0 " " without + 0 " " procs + 0
    }'
}

cpu_probe_darwin() {
    local complete=1 f
    if [ "$ARCH_NORM" = "arm64" ]; then printf 'absent 0 0 0'; return; fi
    if [ "$(sysctl -n sysctl.proc_translated 2>/dev/null || echo 0)" = "1" ]; then
        printf 'absent 0 0 0'; return
    fi
    for f in hw.optional.avx512f hw.optional.avx512bw hw.optional.avx512vbmi hw.optional.bmi2; do
        case $(sysctl -n "$f" 2>/dev/null || echo "") in
            0) printf 'absent 0 0 0'; return ;;
            1) : ;;
            *) complete=0 ;;
        esac
    done
    if [ "$complete" -eq 1 ]; then printf 'present 1 0 1'; else printf 'unknown 0 0 0'; fi
}

cpu_probe() {
    local raw
    if [ -r /proc/cpuinfo ] && grep -q . /proc/cpuinfo 2>/dev/null; then
        raw=$(cpu_from_text < /proc/cpuinfo)
        CPU_SOURCE=/proc/cpuinfo
    elif [ "$OS" = "Darwin" ] && have sysctl; then
        raw=$(cpu_probe_darwin)
        CPU_SOURCE="sysctl"
    else
        CPU_STATE="unknown"
        CPU_SOURCE="无 /proc/cpuinfo，CPU 条件未知"
        CPU_COUNTS="0 0 0"
        return
    fi
    CPU_STATE=$(printf '%s' "$raw" | cut -d' ' -f1)
    CPU_COUNTS=$(printf '%s' "$raw" | cut -d' ' -f2-)
}

# 归一化架构名
norm_arch() {
    case $(lower "${1:-}") in
        amd64|x86_64|x64)      printf 'amd64' ;;
        arm64|aarch64)         printf 'arm64' ;;
        386|x86|i386|i686)     printf '386' ;;
        arm|arm32|riscv64|s390x|ppc64|ppc64le|loong64|loongarch64|sparcv9)
                               lower "${1:-}" ;;
        *)                     printf '' ;;
    esac
}

# 结合架构与 CPU 采集结果 -> present|absent|mixed|unknown
cpu_assess() {
    local arch st
    arch=$(norm_arch "${1:-}")
    st=${2:-unknown}
    if [ -z "$arch" ]; then printf 'unknown'; return; fi
    if [ "$arch" != "amd64" ]; then printf 'absent'; return; fi
    case $st in
        present|absent|mixed) printf '%s' "$st" ;;
        *) printf 'unknown' ;;
    esac
}

# ---------------------------------------------------------------------------
# JDK release 元数据
# ---------------------------------------------------------------------------
release_snapshot() {
    local file=$1 data LC_ALL=C
    [[ -f $file && -r $file ]] || return 1
    # GNU dd also makes the open nonblocking if the path is replaced with a FIFO.
    if [[ ${RELEASE_NONBLOCK:-false} == true ]]; then
        data=$(dd if="$file" iflag=nonblock,fullblock bs="$((JDK_RELEASE_BYTE_LIMIT + 1))" count=1 2>/dev/null && printf .) || return 1
    else
        data=$(head -c "$((JDK_RELEASE_BYTE_LIMIT + 1))" -- "$file" 2>/dev/null && printf .) || return 1
    fi
    data=${data%.}
    (( ${#data} <= JDK_RELEASE_BYTE_LIMIT )) || return 1
    printf '%s' "$data"
}

release_is_jdk() {
    local data
    data=$(release_snapshot "$1") || return 1
    [[ $'\n'$data == *$'\n'JAVA_VERSION=* || $'\n'$data == *$'\n'JAVA_RUNTIME_VERSION=* ]]
}

release_value() {
    local data=$1 key=$2
    [ -n "$data" ] || return 0
    LC_ALL=C awk -v k="$key" -v limit="$JDK_RELEASE_FIELD_LIMIT" '
        {
            line = $0
            sub(/\r$/, "", line)
            i = index(line, "=")
            if (i <= 0) next
            key = substr(line, 1, i - 1)
            val = substr(line, i + 1)
            gsub(/^[ \t]+|[ \t]+$/, "", key)
            gsub(/^[ \t]+|[ \t]+$/, "", val)
            gsub(/^"|"$/, "", val)
            if (key == k) { if (length(val) <= limit) print val; exit }
        }' <<< "$data" 2>/dev/null
}

release_get() {
    local data
    data=$(release_snapshot "$1") || return 0
    release_value "$data" "$2"
}

# 旧版 JRE 仅在父目录确有可读 release 时归一化，避免丢失独立 JRE 的文件证据。
normalize_java_root() {
    local root=${1%/}
    if [[ ${root##*/} == jre && ( ! -f $root/release || ! -r $root/release ) &&
          -f ${root%/*}/release && -r ${root%/*}/release ]]; then
        root=${root%/*}
    fi
    printf '%s' "$root"
}

# java 可执行文件 -> JDK/JRE Home（兼容 .../jre/bin/java 的旧布局）。
java_root_of() {
    local p=${1:-} root
    root=$(dirname "$(dirname "$p")")
    normalize_java_root "$root"
}

# 缺少 release 版本时，读取本机实际运行库/启动器所属的 OpenJDK 8 RPM 包。
# 不执行 java，不根据目录名称推测；仅供磁盘安装清点，不能证明进程运行版本。
installation_rpm_metadata() {
    local root=$1 file row name version vendor pattern
    rpm_meta=
    have rpm && have timeout || return 1
    pattern='^1\.8\.0\.([0-9]+)\.b([0-9]+)$'
    while IFS= read -r -d '' file; do
        [ -f "$file" ] || continue
        java_pkg_reserve || return 1
        file=$(real_path "$(resolve_symlinks "$file")")
        row=$(java_pkg_command rpm -qf --qf '%{NAME}\t%{VERSION}\t%{VENDOR}\n' -- "$file") || continue
        # 多包归属或非预期包名不作为确定版本证据。
        [[ $row != *$'\n'* ]] || continue
        IFS=$'\t' read -r name version vendor <<< "$row"
        case $name in java-1.8.0-openjdk|java-1.8.0-openjdk-headless|java-1.8.0-openjdk-devel) ;; *) continue ;; esac
        [[ $version =~ $pattern ]] || continue
        version="1.8.0_${BASH_REMATCH[1]}-b${BASH_REMATCH[2]}"
        # RPM 的包名明确标识 OpenJDK；保留真实厂商，不伪造发行商信息。
        printf -v rpm_meta '%s\t%s\t%s\t%s' "$version" "$vendor" "$name" "$file"
        return 0
    done < <(jdk_library_files "$root"; printf '%s\0' "$root/bin/java" "$root/jre/bin/java" 2>/dev/null || :)
    return 1
}

