java_pkg_reserve() {
    java_pkg_deadline=${java_pkg_deadline:-$((SECONDS + JAVA_PACKAGE_TOTAL_TIMEOUT))}
    if (( java_pkg_attempts >= JAVA_PACKAGE_LOOKUP_LIMIT || SECONDS >= java_pkg_deadline )); then
        java_pkg_limited=true
        return 1
    fi
    java_pkg_attempts=$((java_pkg_attempts + 1))
}

java_pkg_command() {
    local limiter seconds=$PACKAGE_QUERY_TIMEOUT
    limiter=$(type -P timeout || type -P gtimeout) || return 1
    if (( seconds > java_pkg_deadline - SECONDS )); then seconds=$((java_pkg_deadline - SECONDS)); fi
    (( seconds > 0 )) || return 1
    bounded_command "$limiter" "$seconds" "$PACKAGE_OUTPUT_BYTE_LIMIT" "$@" 2>/dev/null
}

java_pkg_build() {
    local manager=$1 raw=${2##*:} pattern
    case $manager in
        rpm) pattern='^([0-9]+(\.[0-9]+)+)\.([0-9]+)-' ;;
        apk) pattern='^([0-9]+(\.[0-9]+)+)_p([0-9]+)-' ;;
        *)   pattern='^([0-9]+(\.[0-9]+)+)\+([0-9]+)($|[-.])' ;;
    esac
    [[ $raw =~ $pattern ]] || return 1
    printf '%s+%s' "${BASH_REMATCH[1]}" "${BASH_REMATCH[3]}"
}

java_pkg_compare() {
    local manager=$1 installed=$2 fixed=$3 a b av ar bv br result rc=0
    case $manager in
        dpkg)
            java_pkg_command dpkg --compare-versions "$installed" ge "$fixed" >/dev/null || rc=$?
            case $rc in 0) printf meets_vendor_reference ;; 1) printf below_vendor_reference ;; esac ;;
        apk)
            result=$(java_pkg_command apk version -t "$installed" "$fixed") || return 0
            case $result in '='|'>') printf meets_vendor_reference ;; '<') printf below_vendor_reference ;; esac ;;
        rpm)
            a=${installed%%:*}; b=${fixed%%:*}
            if [[ $fixed != *:* ]]; then a=0 b=0; fi
            [[ $a =~ ^[0-9]{1,8}$ && $b =~ ^[0-9]{1,8}$ ]] || return 0
            if (( 10#$a != 10#$b )); then
                if (( 10#$a > 10#$b )); then printf meets_vendor_reference; else printf below_vendor_reference; fi
                return
            fi
            a=${installed#*:}; b=${fixed#*:}
            av=${a%-*}; ar=${a##*-}; bv=${b%-*}; br=${b##*-}
            local safe='^[a-zA-Z0-9.+_~^]+$'
            [[ $av =~ $safe && $ar =~ $safe && $bv =~ $safe && $br =~ $safe ]] || return 0
            result=$(java_pkg_command rpm --eval "%{lua:local c=rpm.vercmp('$av','$bv'); if c==0 then c=rpm.vercmp('$ar','$br') end; print(c)}") || return 0
            case $result in 0|1) printf meets_vendor_reference ;; -1) printf below_vendor_reference ;; esac ;;
    esac
}


java_package_probe() {
    local path=$1 distro=$2 branch=$3 manager data name source version owned owner sv installed vendor srpm
    local reference= advisory= patch=unknown details=
    local token='^[a-zA-Z0-9][a-zA-Z0-9.+:_~^-]{0,127}$'
    case $distro in
        debian|ubuntu)
            manager=dpkg
            data=$(java_pkg_command dpkg-query -S -- "$path") || return 1
            [[ $data == *': '* && $data != *$'\n'* ]] || return 1
            owner=${data%%: *}; owned=${data#*: }
            [[ $owner =~ $token && $owned == "$path" ]] || return 1
            data=$(java_pkg_command dpkg-query -W '-f=${binary:Package}\t${Version}\t${source:Package}\t${source:Version}\t${db:Status-Status}\n' -- "$owner") || return 1
            [[ $data != *$'\n'* ]] || return 1
            IFS=$'\t' read -r name version source sv installed <<< "$data"
            [[ $name == "$owner" && $source == openjdk-* && $version == "$sv" && $installed == installed &&
               ( ${name%%:*} == "$source" || ${name%%:*} == "$source"-* ) ]] || return 1 ;;
        rocky|rhel|almalinux|amzn)
            manager=rpm
            data=$(java_pkg_command rpm -qf --qf '%{NAME}\t%{EPOCHNUM}:%{VERSION}-%{RELEASE}\t%{VENDOR}\t%{SOURCERPM}\n' -- "$path") || return 1
            [[ $data != *$'\n'* ]] || return 1
            IFS=$'\t' read -r name version vendor srpm <<< "$data"
            [[ $srpm == *.src.rpm ]] || return 1
            source=${srpm%.src.rpm}; source=${source%-*}; source=${source%-*}
            [[ $source == java-* && ( $name == "$source" || $name == "$source-headless" ) ]] || return 1
            case $distro:$(lower "$vendor") in
                rhel:*'red hat'*|rocky:*rocky*|almalinux:*almalinux*|amzn:*amazon*) ;;
                *) return 1 ;;
            esac ;;
        alpine)
            manager=apk
            data=$(java_pkg_command apk info -W -- "$path") || return 1
            [[ $data == *' is owned by '* && $data != *$'\n'* ]] || return 1
            owned=${data% is owned by *}; data=${data##* is owned by }
            [[ ${owned#/} == "${path#/}" && $data =~ ^(openjdk[0-9]+(-[a-z]+)*)-([0-9].*)$ ]] || return 1
            name=${BASH_REMATCH[1]}; version=${BASH_REMATCH[3]}; source=${name%%-*}
            case ${name#"$source"} in ""|-jre|-jre-headless|-jdk) ;; *) return 1 ;; esac ;;
        *) return 1 ;;
    esac
    [[ $name =~ $token && $source =~ $token && $version =~ $token ]] || return 1
    IFS=$'\t' read -r reference advisory < <(java_package_rules | awk -F '\t' -v m="$manager" -v d="$distro" -v b="$branch" -v p="$source" '$1==m && $2==d && $3==b && $4==p {print $5 "\t" $6; exit}') || :
    if [[ -n $reference ]]; then
        patch=$(java_pkg_compare "$manager" "$version" "$reference")
    fi
    printf '%s\037%s\037%s\037%s\037%s\037%s\037%s' "$manager" "$name" "$version" "$reference" "$advisory" "${patch:-unknown}" "$details"
}

java_package_evidence() {
    java_package_json=
    java_package_applies=false
    local path=$1 identity=$2 build=$3 key data idx m name version baseline advisory patch details package_build runtime_build agrees=false
    [[ $OS == Linux && -n $path && -n $identity ]] || return 0
    [[ -n ${JAVA_PKG_DISTRO:-} ]] || return 0
    path=$(readlink -f -- "$path" 2>/dev/null) || return 0
    [[ $path == */libjvm.so && -f $path && $path != *[[:cntrl:]]* && $(file_id "$path") == "$identity" ]] || return 0
    printf -v key '%q:%s' "$path" "$identity"
    for ((idx=0; idx<java_pkg_count; idx++)); do
        [[ ${java_pkg_keys[idx]} != "$key" ]] || break
    done
    if ((idx == java_pkg_count)); then
        java_pkg_reserve || return 0
        data=$(java_package_probe "$path" "$JAVA_PKG_DISTRO" "$JAVA_PKG_BRANCH") || data=
        java_pkg_keys[idx]=$key
        java_pkg_results[idx]=$data
        java_pkg_count=$((java_pkg_count + 1))
    else
        data=${java_pkg_results[idx]}
    fi
    [[ -n $data && $(file_id "$path") == "$identity" ]] || return 0
    IFS=$'\037' read -r m name version baseline advisory patch details <<< "$data"
    package_build=$(java_pkg_build "$m" "$version") || package_build=
    runtime_build=$(java_pkg_build jvm "$build") || runtime_build=
    if [[ -z $runtime_build && $m == apk ]]; then runtime_build=$(java_pkg_build apk "$build") || runtime_build=; fi
    if [[ -n $package_build && $package_build == "$runtime_build" ]]; then
        agrees=true
        [[ $patch != meets_vendor_reference ]] || java_package_applies=true
    fi
    java_package_json=$(printf '{"manager":%s,"distribution":%s,"distribution_version":%s,"name":%s,"version":%s,"reference_version":%s,"advisory":%s,"patch_status":%s,"release_build_matches":%s%s}' \
        "$(jstr "$m")" "$(jstr "$JAVA_PKG_DISTRO")" "$(jstr "$JAVA_PKG_BRANCH")" "$(jstr "$name")" "$(jstr "$version")" \
        "$(jstr "$baseline")" "$(jstr "$advisory")" "$(jstr "$patch")" "$agrees" "$details")
}

java_package_context() {
    [[ $OS == Linux && -f /etc/os-release ]] || return 0
    JAVA_PKG_DISTRO=$(release_get /etc/os-release ID)
    JAVA_PKG_BRANCH=$(release_get /etc/os-release VERSION_ID)
    case $JAVA_PKG_DISTRO in
        debian) JAVA_PKG_BRANCH=$(release_get /etc/os-release VERSION_CODENAME) ;;
        rhel|rocky|almalinux) JAVA_PKG_BRANCH=${JAVA_PKG_BRANCH%%.*} ;;
        alpine)
            case $JAVA_PKG_BRANCH in
                *_alpha*) JAVA_PKG_BRANCH=edge ;;
                *.*.*) JAVA_PKG_BRANCH=${JAVA_PKG_BRANCH%.*} ;;
            esac ;;
        ubuntu|amzn) ;;
        *) JAVA_PKG_DISTRO= ;;
    esac
}

java_name() {
    case ${1##*/} in
        [jJ][aA][vV][aA]|[jJ][aA][vV][aA][wW]|[jJ][aA][vV][aA].[eE][xX][eE]|[jJ][aA][vV][aA][wW].[eE][xX][eE]) return 0 ;;
    esac
    return 1
}

# 列出待盘点的 JDK Home
# 从 .../lib/server/libjvm.so 反推运行时根目录（不含 /proc 前缀）

# One unsorted directory stream at a time. GNU find can enumerate a whole
# directory before its downstream consumer sees the first entry.
directory_entries() {
    LC_ALL=C ls -1fb -- "$1" 2>/dev/null || printf '\n'
}

directory_device() {
    if [[ $OS == Darwin ]]; then stat -Lf '%d' "$1" 2>/dev/null
    else stat -Lc '%d' -- "$1" 2>/dev/null
    fi
}

# Decode only the kernel's mountinfo fields. Quoted keys preserve path boundaries.
java_mount_snapshot() {
    local id parent dev root mount options tail path key filesystem
    [[ $OS == Linux && -r /proc/self/mountinfo ]] || return 0
    while IFS=' ' read -r id parent dev root mount options tail; do
        [[ -n $mount && " $tail" == *" - "* ]] || continue
        printf -v path '%b' "$mount"
        printf -v key '%q' "$path"
        java_mounts+="$key"$'\n'
        filesystem=${tail##* - }
        filesystem=${filesystem#- }
        case ${filesystem%% *} in
            autofs|nfs|nfs4|cifs|smb3|9p|ceph|glusterfs|lustre|fuse|fuse.*)
                java_remote_mounts+="$key"$'\n' ;;
        esac
    done < <(head -c 2097152 /proc/self/mountinfo)
}

java_path_on_remote_mount() {
    local path=$1 key
    [[ -n ${java_remote_mounts:-} && $java_remote_mounts != $'\n' ]] || return 1
    [[ $path == /* ]] || path=$PWD/$path
    while :; do
        printf -v key '%q' "$path"
        [[ $java_remote_mounts != *$'\n'"$key"$'\n'* ]] || return 0
        [[ $path != / ]] || return 1
        path=${path%/*}
        path=${path:-/}
    done
}

java_default_directory() {
    if java_path_on_remote_mount "$1"; then
        printf 'mount_skipped\n' >> "$coverage"
        return 1
    fi
    [[ -d $1 ]]
}

java_disk_launcher() {
    local search=${PATH:-}: dir file target
    while [[ $search == *:* ]]; do
        dir=${search%%:*}; search=${search#*:}
        file=${dir:-.}/java
        if java_path_on_remote_mount "$file"; then continue; fi
        if [[ -L $file ]]; then
            target=$(readlink -- "$file" 2>/dev/null) || continue
            if [[ $target != /* ]]; then target=${file%/*}/$target; fi
            if java_path_on_remote_mount "$target"; then continue; fi
        fi
        if [[ -f $file && -x $file ]]; then printf '%s' "$file"; return; fi
    done
    return 1
}

walk_java_tree() {
    local path=$1 depth=$2 entry name child device mount_key
    if (( entries_remaining <= 0 || dirs_remaining <= 0 )); then
        printf 'entry_limit\n' >> "$coverage"
        return 1
    fi
    entries_remaining=$((entries_remaining - 1))
    if (( depth > 0 )); then
        device=$(directory_device "$path") || { printf 'error\n' >> "$coverage"; return 0; }
        [[ $device == "$root_device" ]] || { printf 'mount_skipped\n' >> "$coverage"; return 0; }
    fi
    case $kind in
        discover)
            if (( depth > 0 )) && release_is_jdk "$path/release"; then jdk_root_record "$path"; fi ;;
        discover_mac)
            if (( depth == 3 )) && [[ $path == */Contents/Home ]] &&
                    release_is_jdk "$path/release"; then jdk_root_record "$path"; fi ;;
    esac
    (( depth < max_depth )) || return 0
    dirs_remaining=$((dirs_remaining - 1))
    while IFS= read -r entry; do
        [[ -n $entry ]] || { printf 'error\n' >> "$coverage"; return 0; }
        printf -v name '%b' "${entry//\\ / }"
        [[ $name != . && $name != .. ]] || continue
        if (( entries_remaining <= 0 )); then
            printf 'entry_limit\n' >> "$coverage"
            return 1
        fi
        child=${path%/}/$name
        printf -v mount_key '%q' "$child"
        if [[ ${java_mounts:-} == *$'\n'"$mount_key"$'\n'* ]]; then
            printf 'mount_skipped\n' >> "$coverage"
            entries_remaining=$((entries_remaining - 1))
        elif [[ ( $kind == discover || $kind == discover_mac ) && $name == .* ]]; then
            entries_remaining=$((entries_remaining - 1))
        elif [[ ! -L $child && -d $child ]]; then
            walk_java_tree "$child" "$((depth + 1))" || return 1
        else
            entries_remaining=$((entries_remaining - 1))
            if [[ $kind == library && $name == libjvm.so ]]; then
                printf '%s\0' "$child"
            fi
            if [[ $kind == discover && -L $child && -d $child ]] && release_is_jdk "$child/release"; then
                jdk_root_record "$child"
            fi
            if [[ $kind == discover_mac && $depth == 0 && -L $child ]] &&
                    release_is_jdk "$child/Contents/Home/release"; then
                jdk_root_record "$child/Contents/Home"
            fi
        fi
    done < <(directory_entries "$path" | head -n "$((entries_remaining + 3))")
    return 0
}

walk_java_root() {
    local path=$1 max_depth=$2 kind=$3 root_device
    (( entries_remaining > 0 && dirs_remaining > 0 )) || { printf 'entry_limit\n' >> "$coverage"; return 1; }
    root_device=$(directory_device "$path") || { printf 'error\n' >> "$coverage"; return 0; }
    walk_java_tree "$path" 0
}

jdk_library_files() {
    local home=$1 tree coverage=${ROOT_COVERAGE_FILE:-/dev/null}
    local entries_remaining=$JDK_LIBRARY_ENTRY_LIMIT dirs_remaining=$DIRECTORY_WALK_LIMIT
    for tree in "$home/lib" "$home/jre/lib"; do
        [[ -d $tree ]] || continue
        walk_java_root "$tree" 3 library || break
    done
}


# Record each path with a NUL delimiter, including names containing newlines.
jdk_root_record() (
    local root=$1
    if CDPATH= cd -P -- "$root" 2>/dev/null; then root=$PWD; fi
    root=$(normalize_java_root "$root"; printf '.')
    printf '%s\0' "${root%.}"
)

list_roots() {
    local d j coverage=$ROOT_COVERAGE_FILE
    local entries_remaining=$DIRECTORY_ENTRY_LIMIT dirs_remaining=$DIRECTORY_WALK_LIMIT
    if [ -n "${JAVA_HOME:-}" ] && java_default_directory "$JAVA_HOME"; then
        jdk_root_record "$JAVA_HOME"
    fi

    if j=$(java_disk_launcher); then
        j=$(resolve_symlinks "$j")
        if [ "$OS" != Darwin ] || [ "$j" != /usr/bin/java ]; then
            jdk_root_record "$(java_root_of "$j")"
        fi
    fi

    if [[ -n ${HOME:-} ]]; then
        d=${SDKMAN_DIR:-$HOME/.sdkman}/candidates/java
        if java_default_directory "$d"; then walk_java_root "$d" 1 discover || return 0; fi
        d=${GRADLE_USER_HOME:-$HOME/.gradle}/jdks
        if java_default_directory "$d"; then walk_java_root "$d" 2 discover || return 0; fi
    fi

    case $OS in
        Darwin)
            d=/Library/Java/JavaVirtualMachines
            if [[ -d $d ]]; then walk_java_root "$d" 3 discover_mac || return 0; fi
            d=${HOME:-}/Library/Java/JavaVirtualMachines
            if [[ -n ${HOME:-} && -d $d ]]; then walk_java_root "$d" 3 discover_mac || return 0; fi ;;
        Linux)
            for d in /usr/lib/jvm /usr/lib64/jvm /usr/java /opt/java /opt /usr/local /usr/local/java; do
                java_default_directory "$d" || continue
                walk_java_root "$d" 1 discover || return 0
            done ;;
    esac

}

# ---------------------------------------------------------------------------
# 构建判定（版本 -> fixed|unfixed|outside_scope|candidate|unknown + 依据）
# ---------------------------------------------------------------------------
range_assess() {
    local v=$1 base major first last fixed fixed_note
    if [[ $v =~ ^[0-9]+$ ]]; then
        printf 'unknown\t仅有 Java 主版本号（%s），缺少可供范围判定的版本细节' "$v"
        return
    fi
    base=${v%%+*}
    major=${base%%.*}
    major=${major//[!0-9]/}
    case $major in
        17) first="17.0.6";    last="17.0.21.0.3";  fixed="17.0.21.1"
            fixed_note="17.0.21.1（Oracle）/ 17.0.21.1.2（Corretto）" ;;
        21) first="21.0.0";          last="21.0.13.0.3";  fixed="21.0.13.1"
            fixed_note="21.0.13.1（Oracle）/ 21.0.13.1.2（Corretto）" ;;
        25) first="25.0.0";          last="25.0.5.0.3";   fixed="25.0.5.1"
            fixed_note="25.0.5.1（Oracle）/ 25.0.5.1.2（Corretto）" ;;
        27) first="27.0.0";          last="27.0.1.0.3";   fixed="27.0.1.1"
            fixed_note="27.0.1.1（Oracle）/ 27.0.1.1.4（Corretto）" ;;
        8|11)
            printf 'outside_scope\tJava %s 标准版本不在 Oracle 公布的受影响构建列表内' "$major"
            return ;;
        '')
            printf 'unknown\t无法从版本串中解析主版本号'
            return ;;
        *)
            printf 'unknown\tJava %s 不在已核对的受影响范围表（17/21/25/27）内，需按厂商公告确认' "$major"
            return ;;
    esac

    if [ "$major" = 17 ] && [ "$(vcmp "$base" "$first")" = 0 ]; then
        local build_number=""
        local build_pattern='\+([0-9]+)'
        if [[ $v =~ $build_pattern ]]; then build_number=${BASH_REMATCH[1]}; fi
        if [ -z "$build_number" ] || ! vge "$build_number" 10; then
            printf 'unknown\tJava 17.0.6 缺少已核实的受影响构建号（基线 +10）'
            return
        fi
    fi

    if vge "$base" "$fixed"; then
        printf 'candidate\t需核对厂商及完整修复构建（参考 %s）' "$fixed_note"
    elif [ -n "$first" ] && vlt "$base" "$first"; then
        printf 'outside_scope\t版本早于公开受影响范围（首受影响 %s）' "$first"
    elif vle "$base" "$last"; then
        printf 'unfixed\t版本落在公开受影响范围（至 %s），修复构建为 %s' "$last" "$fixed_note"
    else
        printf 'unknown\t版本位于"最后已知受影响构建 %s"与"首个已知修复构建 %s"之间，没有公开构建落在此处；请直接升级到 %s' \
            "$last" "$fixed" "$fixed_note"
    fi
}

recognized_jdk_vendor() {
    local v vm
    v=$(lower "${1:-}")
    vm=$(lower "${2:-}")
    if [ -n "$vm" ]; then
        case $vm in
            *hotspot*|*openjdk*) : ;;
            *) return 1 ;;
        esac
    fi
    case $v in
        openjdk|debian|ubuntu|canonical|alpine|"rocky linux"|"rocky enterprise software foundation"|almalinux|"eclipse adoptium"|temurin|"amazon.com inc."|"amazon.com inc"|\
        microsoft|"azul systems, inc."|azul|"red hat, inc."|"red hat"|bellsoft|"sap se"|\
        "eclipse foundation"|"oracle corporation"|oracle)
            return 0 ;;
    esac
    case $vm in
        *openjdk*) return 0 ;;
    esac
    return 1
}

build_assess() {
    local version=${1:-} vendor=${2:-} product=${3:-} vm=${4:-}
    local v vl pl vml base major

    v=$(lower "$(trim "$version")")
    vl=$(lower "$(trim "$vendor")")
    pl=$(lower "$(trim "$product")")
    vml=$(lower "$(trim "$vm")")

    if [ -z "$v" ]; then
        printf 'unknown\t没有可用的 Java 版本元数据（release/version 输出缺失）'
        return
    fi

    case $vml in
        *openj9*)
            printf 'outside_scope\t识别到 OpenJ9 VM；该 CVE 属于 HotSpot intrinsic，不在影响范围'
            return ;;
    esac

    base=${v%%+*}
    major=${base%%.*}
    major=${major//[!0-9]/}

    # Oracle Java 8 Performance Pack boundaries come from the vendor advisory.
    local legacy_pattern='^(1\.8\.0_[0-9]+(-[A-Za-z0-9.-]+)?|8u[0-9]+(-?b[0-9]+)?(-perf)?)$'
    if [[ $v =~ $legacy_pattern ]]; then
        if [[ $vl == oracle || $vl == "oracle corporation" ]]; then
            case $v in
                8u511b33-perf|1.8.0_511-perf-b33)
                    printf 'unfixed\tOracle Java SE 8u511b33-perf 在受影响列表内'
                    return ;;
                8u513-perf|1.8.0_513-perf-b4|1.8.0_513-perf-b04)
                    printf 'fixed\tOracle Java SE 8u513-perf 修复构建'
                    return ;;
            esac
        fi
        local update legacy_update_pattern='^(1\.8\.0_|8u)([0-9]+)(-b[0-9]+|b[0-9]+)?$'
        if [[ $v =~ $legacy_update_pattern ]]; then
            update=${BASH_REMATCH[2]}
            # 明确的 OpenJDK 产品证据支持 RPM 厂商为 CentOS/Rocky 等发行方的旧构建。
            if [ "$pl" = openjdk ]; then
                printf 'outside_scope\t已识别的标准 OpenJDK 8 发行构建不在本次披露范围内'
                return
            fi
            case $vl in
                openjdk|debian|ubuntu|canonical|"eclipse adoptium"|temurin|"amazon.com inc."|"amazon.com inc"|\
                "azul systems, inc."|azul|"red hat, inc."|"red hat")
                    printf 'outside_scope\t已识别的标准 OpenJDK 8 发行构建不在本次披露范围内'
                    return ;;
                oracle|"oracle corporation")
                    if vlt "$update" 511; then
                        printf 'outside_scope\t已识别的 Oracle Java 8 标准旧构建不在本次披露范围内'
                        return
                    fi ;;
            esac
        fi
        printf 'unknown\tJava 8 构建缺少适用的厂商规则'
        return
    fi

    # ---- 精确规则：OpenJDK / Oracle OpenJDK 构建 ----
    if [[ ( $vl == openjdk && ( -z $pl || $pl == openjdk ) ) ||
          ( ( $vl == oracle || $vl == "oracle corporation" ) && $pl == openjdk ) ]]; then
        case $v in
            17.0.21.1+2|21.0.13.1+2|25.0.5.1+2|27.0.1.1+4)
                printf 'fixed\tOpenJDK 修复 GA 标签（%s）' "${base}"
                return ;;
            17.0.21|17.0.21.0.3|21.0.13|21.0.13.0.3|25.0.5|25.0.5.0.3|27.0.1|27.0.1.0.3)
                printf 'unfixed\tOpenJDK 受影响 GA 标签（%s），缺少变更 8393212 的尾块长度检查' "${base}"
                return ;;
        esac
    fi

    # ---- 精确规则：Oracle 产品线 ----
    if [ "$vl" = "oracle" ] || [ "$vl" = "oracle corporation" ]; then
        case $pl in
            "oracle java se")
                case $base in
                    8u511b33-perf|1.8.0_511-perf-b33|17.0.21.0.3|21.0.13.0.3|25.0.5.0.3|27.0.1.0.3)
                        printf 'unfixed\tOracle Java SE 受影响构建（%s）' "$base"
                        return ;;
                    17.0.21.1|21.0.13.1|25.0.5.1|27.0.1.1)
                        case $v in
                            "$base+4") printf 'fixed\tOracle Java SE 修复构建（%s+4）' "$base"; return ;;
                            "$base"+*)
                                local oracle_lts_pattern='^\+4-lts(-[0-9]+)?$'
                                if [[ ${v#"$base"} =~ $oracle_lts_pattern ]]; then
                                    printf 'fixed\tOracle Java SE 修复构建（%s）' "$v"
                                    return
                                fi ;;
                        esac
                        printf 'unknown\tOracle Java SE 版本缺少已核实的完整修复构建号（%s）' "$v"
                        return
                        ;;
                esac ;;
            "oracle graalvm for jdk")
                case $base in
                    17.0.21.0.3|21.0.13.0.3)
                        printf 'unfixed\tOracle GraalVM for JDK 受影响构建（%s）' "$base"; return ;;
                esac ;;
            "oracle graalvm enterprise edition")
                case $base in
                    21.3.20.0.3)
                        printf 'unfixed\tOracle GraalVM Enterprise Edition 受影响构建（%s）' "$base"; return ;;
                esac ;;
        esac
    fi

    if [[ $vl == "amazon.com inc." || $vl == "amazon.com inc" ]]; then
        local distribution
        distribution=$(lower "${5:-}")
        distribution=${distribution#corretto-}
        case "$v:$distribution" in
            17.0.21.1.2:*|21.0.13.1.2:*|25.0.5.1.2:*|27.0.1.1.4:*|\
            17.0.21.1+2:17.0.21.1.2|17.0.21.1+2-lts:17.0.21.1.2|\
            21.0.13.1+2:21.0.13.1.2|21.0.13.1+2-lts:21.0.13.1.2|\
            25.0.5.1+2:25.0.5.1.2|25.0.5.1+2-lts:25.0.5.1.2|\
            27.0.1.1+4:27.0.1.1.4|27.0.1.1+4-fr:27.0.1.1.4)
                printf 'fixed\tAmazon Corretto 已核实的修复发行版本'
                return ;;
        esac
    fi

    # ---- 精确规则：Debian 构建 ----
    if [ "$vl" = "debian" ]; then
        case $v in
            17.0.19+10-1~deb12u2|17.0.21+9-1~deb12u1|17.0.21.0.3+1-1|\
21.0.12.1+1-1~deb13u1|21.0.13+9-1~deb13u2|21.0.13+9-1-deb13u2-debian|21.0.13.0.3+1-1|\
25.0.3+9-2~deb13u1|25.0.5+8-1~deb13u1|25.0.5+8-1|25.0.5.0.3+1-3|27.0.1.0.3+1-1)
                printf 'unfixed\tDebian 跟踪器所列受影响包版本（%s）' "$v"
                return ;;
        esac
    fi

    case $pl in
        *graalvm*)
            printf 'candidate\tGraalVM 需按其具体产品与构建确认补丁证据'
            return ;;
    esac

    case $vl:$base in
        "red hat, inc.:"21.0.13.0.9|"red hat, inc.:"25.0.5.0.8|"red hat:"21.0.13.0.9|"red hat:"25.0.5.0.8|        "rocky linux:"21.0.13.0.9|"rocky linux:"25.0.5.0.8|"rocky enterprise software foundation:"21.0.13.0.9|        "rocky enterprise software foundation:"25.0.5.0.8|almalinux:21.0.13.0.9|almalinux:25.0.5.0.8)
            printf 'unfixed\t已知的旧版企业发行版 OpenJDK 构建'
            return ;;
    esac

    # ---- 版本形态校验 ----
    local version_pattern='^[0-9]{1,3}(\.[0-9]+){0,4}(\+[0-9]+([.-][A-Za-z0-9.~+_-]+)?)?$'
    if [[ ! $v =~ $version_pattern ]]; then
        printf 'unknown\t没有可用的 Java 版本元数据（%s）' "$version"
        return
    fi
    if [ -z "$major" ] || [ "$major" -lt 8 ] || [ "$major" -gt 27 ]; then
        printf 'unknown\tJava %s 超出已核对覆盖范围（8–27）' "${major:-?}"
        return
    fi

    # ---- 范围兜底 ----
    local r assess evidence extra=""
    r=$(range_assess "$v")
    assess=${r%%	*}
    evidence=${r#*	}
    if ! recognized_jdk_vendor "$vendor" "$vm"; then
        extra="（厂商/产品未确认为 OpenJDK 系，按公开 OpenJDK 范围判定）"
        case $assess in
            fixed|unfixed) assess="candidate" ;;
        esac
    fi
    printf '%s\t%s%s' "$assess" "$evidence" "$extra"
}

# ---------------------------------------------------------------------------
# 缓解参数
#   多次出现按最后一个生效；-XX:UseAVX<=2 视为已缓解
# ---------------------------------------------------------------------------



# ---------------------------------------------------------------------------
# 状态合成
#   classify build cpu mitigated arch -> status
# ---------------------------------------------------------------------------
classify() {
    local build=$1 cpu=$2 mit=$3 feff=$4 arch=$5
    case $build in
        fixed|outside_scope) printf 'not_affected'; return ;;
    esac
    if [ "$cpu" = "absent" ]; then printf 'not_affected'; return; fi
    if [ "$build" = "unknown" ]; then printf 'unknown'; return; fi
    if [ "${6:-process}" != "process" ]; then printf 'potential'; return; fi
    if [ "$mit" -eq 1 ] && [ "$feff" -eq 1 ] && [ "$arch" = "amd64" ]; then printf 'mitigated'; return; fi
    if [ "$build" = "unfixed" ] && [ "$cpu" = "present" ] && [ "$mit" -eq 0 ] && [ "$feff" -eq 1 ]; then
        printf 'affected'; return
    fi
    if [ "$build" = "unfixed" ] && [ "$cpu" = "present" ]; then
        printf 'unknown'
    else
        printf 'potential'
    fi
}

# 生成判定依据
make_reason() {
    local status=$1 build=$2 bevid=$3 cpu=$4 mit=$5 arch=$6 hint=${7:-}
    local reason=""
    case $status in
        not_affected)
            case $build in
                fixed)        reason="已确认修复：版本已达到修复构建。" ;;
                outside_scope) reason="不在影响范围：$bevid" ;;
                *)            reason="CPU/架构不满足漏洞条件：需 x86-64 且运行环境可见 avx512f、avx512bw、avx512vbmi、bmi2。" ;;
            esac ;;
        unknown)
            reason="证据不足，无法判定。请核对构建、CPU 和 JVM 生效参数。$bevid" ;;
        mitigated)
            reason="已缓解：JVM 生效参数禁用了 Base64 intrinsic 或将 AVX 级别限制到 2 及以下。" ;;
        affected)
            reason="运行中 JVM 的构建与 CPU 符合受影响条件，生效参数显示相关指令路径未禁用。$bevid" ;;
        potential)
            reason="存在风险线索，需进一步确认：$bevid"
            [ "$mit" -eq 1 ] && reason="$reason 已观察到缓解参数，但未确认其为该 JVM 的有效参数。"
            [ "$cpu" = "mixed" ] && reason="$reason 可见逻辑 CPU 的 AVX-512 特性不一致。"
            [ "$build" = "unfixed" ] && [ "$cpu" = "unknown" ] && reason="$reason CPU 条件未知。"
            ;;
    esac
    [ -n "$hint" ] && reason="$reason $hint"
    printf '%s' "$reason"
}

# ---------------------------------------------------------------------------
# 资产记录：写入 FIND_FILE（以 ASCII 单元分隔符分隔）
#  1 id 2 kind 3 status 4 reason 5 build 6 build_evidence 7 cpu
#  8 version 9 java_home 10 vendor 11 product 12 vm 13 arch
#  14 flags 15 flags_effective 16 container 17 notes
#  18 identity_confidence 19 disk_version 20 disk_vendor 21 disk_product 22 disk_build
# ---------------------------------------------------------------------------
emit_finding() {
    local id kind status reason build bevid cpu version jhome vendor product vm arch flags feff container notes
    id=$(san_field "${1:-}")
    kind=$(san_field "${2:-}")
    status=$(san_field "${3:-}")
    reason=$(san_field "${4:-}")
    build=$(san_field "${5:-}")
    bevid=$(san_field "${6:-}")
    cpu=$(san_field "${7:-}")
    version=$(san_field "${8:-}")
    jhome=$(san_field "${9:-}")
    vendor=$(san_field "${10:-}")
    product=$(san_field "${11:-}")
    vm=$(san_field "${12:-}")
    arch=$(san_field "${13:-}")
    flags=$(san_field "${14:-}")
    feff=$(san_field "${15:-}")
    container=$(san_field "${16:-}")
    notes=$(san_field "${17:-}")
    local identity_confidence disk_hint_version disk_hint_vendor disk_hint_product disk_hint_build package_json flag_probe_json
    identity_confidence=$(san_field "${18:-}")
    disk_hint_version=$(san_field "${19:-}")
    disk_hint_vendor=$(san_field "${20:-}")
    disk_hint_product=$(san_field "${21:-}")
    disk_hint_build=$(san_field "${22:-}")

    package_json=${23:-}
    flag_probe_json=${24:-}

    printf '%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\037%s\n' \
        "$id" "$kind" "$status" "$reason" "$build" "$bevid" "$cpu" "$version" \
        "$jhome" "$vendor" "$product" "$vm" "$arch" "$flags" "$feff" "$container" "$notes" \
        "$identity_confidence" "$disk_hint_version" "$disk_hint_vendor" "$disk_hint_product" "$disk_hint_build" "$package_json" "$flag_probe_json" \
        >> "$FIND_FILE" || die "写入巡检发现失败"
}

add_note() { NOTES="${NOTES:+$NOTES | }$1"; }

# ---------------------------------------------------------------------------
# 采集：JDK 安装目录
# ---------------------------------------------------------------------------
file_id() {
  local raw device inode
  raw=$(stat -Lc '%d %i' -- "$1" 2>/dev/null) || return 1
  read -r device inode <<< "$raw"
  [[ $device =~ ^[0-9]+$ && $inode =~ ^[0-9]+$ ]] || return 1
  # Decode Linux st_dev. Keep inode as text to preserve all 64 bits.
  printf '%s %s %s' "$(( (device >> 8 & 0xfff) | (device >> 32 & 0xfffff000) ))" \
    "$(( (device & 0xff) | (device >> 12 & 0xffffff00) ))" "$inode"
}

jdk_product() {
    local home=$1 vendor=$2 label graal edition release_data=${3-}
    case $(lower "$vendor") in
        openjdk) printf 'OpenJDK' ;;
        oracle|"oracle corporation")
            (( $# >= 3 )) || release_data=$(release_snapshot "$home/release") || release_data=
            graal=$(release_value "$release_data" GRAALVM_VERSION)
            edition=$(lower "$(release_value "$release_data" GRAALVM_EDITION)")
            label=$(lower "$(printf '%s %s %s' "$edition" \
                "$(release_value "$release_data" IMPLEMENTOR_VERSION)" \
                "$(release_value "$release_data" JAVA_RUNTIME_NAME)")")
            case "$label" in
                *"enterprise edition"*|*"graalvm enterprise"*)
                    printf 'Oracle GraalVM Enterprise Edition'
                    return ;;
            esac
            if [[ $edition == ee && $graal == 21.3.* ]]; then
                printf 'Oracle GraalVM Enterprise Edition'
                return
            fi
            case "$graal $label" in
                *graalvm*) printf 'Oracle GraalVM for JDK'; return ;;
            esac
            if [ -n "$graal" ]; then printf 'Oracle GraalVM for JDK'; return; fi
            case $label in
                *"java(tm)"*|*"java se"*) printf 'Oracle Java SE' ;;
                *openjdk*) printf 'OpenJDK' ;;
                *)
                    if [ -f "$home/README" ] &&
                       head -c 65536 "$home/README" 2>/dev/null | grep -q 'Thank you for using the Oracle JDK.'; then
                        printf 'Oracle Java SE'
                    fi ;;
            esac ;;
    esac
}

assess_jdk_build() {
    local home=$1 version=$2 vendor=$3 product=$4 vm=$5 distribution="" graal="" release_data=${6-}
    if [ -n "$home" ]; then
        (( $# >= 6 )) || release_data=$(release_snapshot "$home/release") || release_data=
        distribution=$(release_value "$release_data" IMPLEMENTOR_VERSION)
        if [ "$product" = "Oracle GraalVM Enterprise Edition" ]; then
            graal=$(release_value "$release_data" GRAALVM_VERSION)
            local graal_pattern='^[0-9]+(\.[0-9]+){1,4}$'
            if [[ $graal =~ $graal_pattern ]]; then
                version=$graal
            fi
        fi
    fi
    build_assess "$version" "$vendor" "$product" "$vm" "$distribution"
}

scan_installations() {
    local root version vendor product vm arch notes build cpu status mit flags feff vmname vmtext openj9
    local bevid reason bevid_and_build lib lib_id matched rpm_meta rpm_name rpm_file

    local release_data seen_roots=$'\n' scanned=0 root_key pkg_lib pkg_id java_package_json java_package_applies
    while LC_ALL=C IFS= read -r -d '' root; do
        [ -n "$root" ] || continue
        printf -v root_key '%q' "$root"
        [[ $seen_roots != *$'\n'"$root_key"$'\n'* ]] || continue
        if (( scanned >= JDK_INSTALLATION_LIMIT )); then
            printf 'entry_limit\n' >> "$ROOT_COVERAGE_FILE"
            break
        fi
        scanned=$((scanned + 1))
        seen_roots+="$root_key"$'\n'
        matched=0 pkg_lib= pkg_id=
        while IFS= read -r -d '' lib; do
            [ -f "$lib" ] || continue
            lib_id=$(file_id "$lib") || continue
            if [[ -z $pkg_id ]]; then pkg_lib=$lib pkg_id=$lib_id
            elif [[ $pkg_id != "$lib_id" ]]; then pkg_lib=; fi
            if grep -Fxq -- "$lib_id" "$ACTIVE_FILE"; then matched=1; break; fi
        done < <(jdk_library_files "$root")
        [ "$matched" -eq 0 ] || continue
        NOTES=""
        version=""; vendor=""; product=""; vm=""; arch=""; vmname=""
        build="unknown"; bevid=""

        if release_data=$(release_snapshot "$root/release"); then
            version=$(release_value "$release_data" JAVA_RUNTIME_VERSION)
            [ -n "$version" ] || version=$(release_value "$release_data" JAVA_VERSION)
            vendor=$(release_value "$release_data" IMPLEMENTOR)
            vm=$(release_value "$release_data" JVM_VARIANT)
            vmname=$(release_value "$release_data" JAVA_VM_NAME)
            arch=$(release_value "$release_data" OS_ARCH)
            [ -n "$version" ] || add_note "release 文件中没有 JAVA_VERSION/JAVA_RUNTIME_VERSION"
        else
            add_note "release 元数据缺失、不可读、并非普通文件或超过读取上限"
        fi

        product=$(jdk_product "$root" "$vendor" "$release_data")
        # 老版 CentOS/RHEL OpenJDK 8 可无 release，按实际文件的 RPM 归属补充磁盘版本。
        if [ -z "$version" ]; then
            installation_rpm_metadata "$root" || rpm_meta=""
            if [ -n "$rpm_meta" ]; then
                IFS=$'\t' read -r version vendor rpm_name rpm_file <<< "$rpm_meta"
                product="OpenJDK"
                add_note "磁盘版本来源: RPM 文件归属；包=$rpm_name；厂商=$vendor；文件=$rpm_file"
            else
                add_note "无法从实际文件所属的 OpenJDK 8 RPM 包补充版本；未使用目录名称推测"
            fi
        fi

        if [ -z "$arch" ]; then
            arch=$ARCH_RAW
            add_note "release 缺少 OS_ARCH，按本机架构（$ARCH_RAW）判定"
        fi

        cpu=$(cpu_assess "$arch" "$CPU_STATE")
        bevid_and_build=$(assess_jdk_build "$root" "$version" "$vendor" "$product" "$vm" "$release_data")
        build=$(printf '%s' "$bevid_and_build" | cut -f1)
        bevid=$(printf '%s' "$bevid_and_build" | cut -f2-)

        java_package_evidence "$pkg_lib" "$pkg_id" "$version"
        if [[ $java_package_applies == true && $product != *GraalVM* && ( $build == unknown || $build == candidate ) ]]; then
            build=fixed
            bevid="本机软件包公告与磁盘 JVM 构建一致"
        fi
        flags=""
        feff="false"
        mit=0
        [ "$build" = "" ] && build="unknown"

        vmtext=$(lower "${vm:-} ${vmname:-}")
        case $vmtext in *openj9*) openj9=1 ;; *) openj9=0 ;; esac
        if [ "$openj9" -eq 1 ]; then
            build="outside_scope"
            bevid="运行在 Eclipse OpenJ9（自有 Base64 实现，不经过 HotSpot intrinsic）"
            status="not_affected"
            reason="OpenJ9 不使用 HotSpot 的 Base64 intrinsic，不在本次影响面"
            add_note "OpenJ9 走自有实现；公告未单列该实现，若厂商有相反说明以厂商为准"
        else
            status=$(classify "$build" "$cpu" "$mit" 0 "$(norm_arch "$arch")" installation)
            reason=$(make_reason "$status" "$build" "$bevid" "$cpu" "$mit" "$(norm_arch "$arch")")
        fi

        emit_finding "install:$root" "installation" "$status" "$reason" "$build" "$bevid" \
            "$cpu" "$version" "$root" "$vendor" "$product" "$vm" "$arch" "$flags" "$feff" "" "$NOTES" "" "" "" "" "" "$java_package_json"
    done < <(list_roots)
}

# ---------------------------------------------------------------------------
# 采集：进程
# ---------------------------------------------------------------------------
java_process_start() {
    local stat
    local -a fields
    { IFS= read -r -d '' stat < "/proc/$1/stat"; } 2>/dev/null || :
    [[ -n ${stat:-} ]] || return 0
    IFS=$' \n' read -r -a fields <<< "${stat##*) }"
    printf '%s\n' "${fields[19]:-}"
}

libjvm_meta() {
    local proc=$1 limit=$JVM_MAPS_BYTE_LIMIT used=0 counter=/dev/null ceiling=/dev/null rows
    if [[ -n ${WORK:-} ]]; then
        counter="$WORK/java-maps-bytes"
        ceiling="$WORK/java-maps-limit"
        if [[ -f $counter ]]; then IFS= read -r used < "$counter" || return 1; fi
        (( limit <= JVM_MAPS_TOTAL_BYTE_LIMIT - used )) || limit=$((JVM_MAPS_TOTAL_BYTE_LIMIT - used))
        if (( limit <= 0 )); then : > "$ceiling"; return 1; fi
    fi
    rows=$(
        set -o pipefail
        LC_ALL=C head -c "$((limit + 1))" -- "$proc/maps" 2>/dev/null |
        LC_ALL=C X2_MAP_COUNTER="$counter" X2_MAP_CEILING="$ceiling" \
            awk -v cap="$limit" -v used="$used" '
        BEGIN { counter = ENVIRON["X2_MAP_COUNTER"]; ceiling = ENVIRON["X2_MAP_CEILING"] }
        { bytes += length($0) + 1 }
        /\/libjvm\.so( \(deleted\))?$/ && $5 != "0" {
            dev = $4; inode = $5; path = $0
            for (i = 0; i < 5; i++) sub(/^[[:space:]]*[^[:space:]]+/, "", path)
            sub(/^[[:space:]]+/, "", path)
            if (path !~ /^\//) next
            row = dev "\037" inode "\037" path
            if (!(row in seen)) {
                if (rows >= 32) { too_many = 1; next }
                seen[row] = ++rows
                print row "\037" $1
            }
        }
        END {
            printf "%.0f\n", used + (bytes > cap + 1 ? cap + 1 : bytes) > counter
            if (bytes > cap || too_many) {
                if (counter != "/dev/null") print "limited" > ceiling
                exit 1
            }
        }
        ' 2>/dev/null
    ) || return 1
    printf '%s' "$rows"
}

mapping_identity() {
    local proc=$1 range=$2 expected=$3 disk=$4 mapped
    if [[ $disk == "$expected" ]]; then
        printf 'maps'
        return
    fi
    [[ ${disk##* } == "${expected##* }" && $range =~ ^[[:xdigit:]]+-[[:xdigit:]]+$ ]] || return 1
    mapped=$(file_id "$proc/map_files/$range") || return 2
    [[ $mapped == "$disk" ]] || return 1
    printf 'map_files'
}




# JVM 是否注册了 SIGQUIT 处理器（attach 监听器的前提）



jvm_root_from_lib() {
    local proc=$1 lib=$2 server libdir root
    server=${lib%/*}
    [ "${server##*/}" = "server" ] || { printf ''; return; }
    libdir=${server%/*}
    case ${libdir##*/} in
        amd64|i386) libdir=${libdir%/*} ;;
    esac
    [ "${libdir##*/}" = "lib" ] || { printf ''; return; }
    root="${libdir%/*}"
    if [ -n "$proc" ]; then root="$proc/root$root"; fi
    normalize_java_root "$root"
}

container_hint() {
    local proc=$1 line ns initns
    if [ -r "$proc/cgroup" ]; then
        while IFS= read -r line; do
            case $(lower "$line") in
                *kubepods*)   printf 'kubepods（cgroup 线索）'; return ;;
                *docker*)     printf 'docker（cgroup 线索）'; return ;;
                *libpod*)     printf 'libpod（cgroup 线索）'; return ;;
                *containerd*) printf 'containerd（cgroup 线索）'; return ;;
                */lxc*)       printf 'lxc（cgroup 线索）'; return ;;
                *cri-o*|*crio-*) printf 'cri-o（cgroup 线索）'; return ;;
            esac
        done < "$proc/cgroup"
    fi
    if [ -e "$proc/root/.dockerenv" ]; then printf 'docker（root 标记）'; return; fi
    if [ -e "$proc/root/run/.containerenv" ]; then printf 'container（root 标记）'; return; fi
    ns=$(readlink "$proc/ns/pid" 2>/dev/null || echo "")
    initns=$(readlink /proc/1/ns/pid 2>/dev/null || echo "")
    if [ -n "$ns" ] && [ -n "$initns" ] && [ "$ns" != "$initns" ]; then
        printf '独立 PID 命名空间'
        return
    fi
    printf ''
}

# 从 cmdline 提取启动参数（跳过 -cp/-jar 等及其值）
launcher_flags() {
    local f=$1 arg i=1 n out="" bytes=0 LC_ALL=C args=()
    [ -r "$f" ] || return 0
    while IFS= read -r -d '' arg; do
        bytes=$((bytes + ${#arg} + 1))
        (( bytes <= JVM_CMDLINE_BYTE_LIMIT )) || return 0
        args[${#args[@]}]="$arg"
    done < <(head -c "$((JVM_CMDLINE_BYTE_LIMIT + 1))" -- "$f" 2>/dev/null)
    # A partial final argument or unreadable input supplies no trustworthy estimate.
    [[ -z $arg ]] || return 0
    n=${#args[@]}
    while [ "$i" -lt "$n" ]; do
        arg=${args[$i]}
        case $arg in
            -cp|-classpath|--class-path|-p|--module-path|--upgrade-module-path|\
--add-modules|--limit-modules|--add-exports|--add-opens|--add-reads|\
--patch-module|--source|--enable-native-access)
                i=$((i + 2)); continue ;;
        esac
        case $arg in
            -jar|-m|--module|--module=*|--) break ;;
            -*)
                case $arg in
                    -XX:-UseBASE64Intrinsics|-XX:+UseBASE64Intrinsics) out="$out $arg" ;;
                    -XX:UseAVX=*) out="$out $arg" ;;
                esac ;;
            *) break ;;
        esac
        i=$((i + 1))
    done
    printf '%s' "${out# }"
}

scan_processes() {
    local pid proc exe exe_clean comm named has_jvm maps_ok
    local libmeta libpath libdev libino st mhex nhex verified range expected identity_source identity_rc
    local root root_disp version vendor product vm arch build bevid cpu status reason
    local flags feff mit fn notes container start1 start2
    local bevid_and_build verify_problem libmeta2 libmeta3 vmname vmtext
    local disk_version weak_identity
    local identity_confidence disk_hint_version disk_hint_vendor disk_hint_product disk_hint_build

    local release_data scanned=0 java_package_json java_package_applies
    local host_mount host_root
    host_mount=$(readlink /proc/self/ns/mnt 2>/dev/null || :)
    host_root=$(file_id / || :)
    while IFS= read -r pid; do
        [ -n "$pid" ] || continue
        if (( scanned >= PROCESS_SCAN_LIMIT )); then PROCESS_LIMIT_REACHED=true; break; fi
        scanned=$((scanned + 1))
        proc="/proc/$pid"
        NOTES=""

        if [ ! -d "$proc" ]; then
            continue
        fi

        start1=$(java_process_start "$pid")

        named=0
        if { IFS= read -r comm < "$proc/comm"; } 2>/dev/null; then
            java_name "$comm" && named=1
        fi

        has_jvm=0
        maps_ok=1
        if libmeta=$(libjvm_meta "$proc"); then
            [ -z "$libmeta" ] || has_jvm=1
        else
            maps_ok=0
            if [ -d "$proc" ]; then LIMITED_PROCS=$((LIMITED_PROCS + 1)); fi
        fi
        if (( named || has_jvm || !maps_ok )); then
            exe=$(readlink "$proc/exe" 2>/dev/null || :)
            exe_clean=${exe% (deleted)}
            java_name "$exe_clean" && named=1
        fi
        if [ "$maps_ok" -eq 0 ] && [ "$named" -eq 1 ]; then
            emit_finding "pid:$pid" "process" "unknown" "无法读取进程映射，无法核实运行中 JVM。" \
                "unknown" "进程映射不可读" "$(cpu_assess "$ARCH_RAW" "$CPU_STATE")" \
                "" "" "" "" "" "$ARCH_RAW" "" "false" "" ""
            continue
        fi

        if [ "$named" -eq 0 ] && [ "$has_jvm" -eq 0 ]; then
            continue
        fi

        # File identity and JVM version evidence have independent lifetimes.
        verified=0
        weak_identity=0
        identity_source=""
        disk_version=""
        root=""
        libpath=""
        st=""
        verify_problem=""
        if [[ -n $libmeta && $libmeta != *$'\n'* ]]; then
            IFS=$'\037' read -r libdev libino libpath range <<< "$libmeta"
            mhex=${libdev%%:*}
            nhex=${libdev##*:}
            if [[ $libpath == *" (deleted)" ]]; then
                verify_problem="运行中的 HotSpot 库已被删除，无法核对磁盘文件"
            elif ! st=$(file_id "$proc/root$libpath"); then
                verify_problem="无法读取磁盘上对应的 libjvm.so 文件身份"
            elif [[ $mhex =~ ^[[:xdigit:]]+$ && $nhex =~ ^[[:xdigit:]]+$ ]]; then
                expected="$((16#$mhex)) $((16#$nhex)) $libino"
                identity_rc=0
                identity_source=$(mapping_identity "$proc" "$range" "$expected" "$st") || identity_rc=$?
                case $identity_rc in
                    0) verified=1 ;;
                    2) weak_identity=1 ;;
                    *) verify_problem="无法将运行中映射与磁盘文件关联" ;;
                esac
                if [ "$identity_source" = map_files ] || [ "$weak_identity" -eq 1 ] ||
                   [ "$identity_rc" -ne 0 ]; then
                    add_note "maps 设备号及 inode: $expected；磁盘 stat: $st"
                fi
                if [ "$weak_identity" -eq 1 ]; then
                    add_note "inode 相同但设备号不同，无法读取 map_files 进一步核实"
                fi
                if [ "$verified" -eq 1 ] || [ "$weak_identity" -eq 1 ]; then
                    root=$(jvm_root_from_lib "$proc" "$libpath")
                fi
            fi
        elif [[ -n $libmeta ]]; then
            verify_problem="进程内存在多个不同的 HotSpot 库映射，无法确定运行实体"
        fi

        version=""; vendor=""; product=""; vm=""; arch=""
        release_data=
        if [ -n "$root" ] && release_data=$(release_snapshot "$root/release"); then
            version=$(release_value "$release_data" JAVA_RUNTIME_VERSION)
            [ -n "$version" ] || version=$(release_value "$release_data" JAVA_VERSION)
            vendor=$(release_value "$release_data" IMPLEMENTOR)
            vm=$(release_value "$release_data" JVM_VARIANT)
            vmname=$(release_value "$release_data" JAVA_VM_NAME)
            arch=$(release_value "$release_data" OS_ARCH)
            product=$(jdk_product "$root" "$vendor" "$release_data")
            disk_version=$version
            if [ "$weak_identity" -eq 1 ]; then
                add_note "未关联的磁盘 release 构建: ${disk_version:-未知}"
            fi
            case $identity_source in
                maps) add_note "已映射的 HotSpot 库与磁盘 JDK 的设备号和 inode 一致" ;;
                map_files) add_note "已通过 map_files 核实映射对象与磁盘文件的设备号和 inode" ;;
            esac
            root_disp=${root#"$proc/root"}
            [ -n "$root_disp" ] || root_disp=$root
            libmeta2=$(libjvm_meta "$proc")
            if [ "$libmeta2" != "$libmeta" ]; then
                verify_problem="采集期间进程映射发生变化（可能重启或重新映射）"
            fi
        else
            root_disp=""
            if [ -n "$verify_problem" ]; then
                add_note "$verify_problem；不采用磁盘启动器的版本，避免把已升级的磁盘版本当成运行版本"
            else
                add_note "无法核实 JVM 身份或 release 元数据（可能为不同用户/已删除文件/受限的 /proc）"
            fi
        fi
        [ -n "$arch" ] || arch=$ARCH_RAW

        if { [ "$verified" -ne 1 ] && [ "$weak_identity" -ne 1 ]; } || [ -n "$verify_problem" ]; then
            verify_problem=${verify_problem:-无法核实运行中 JVM 映像}
            container=$(container_hint "$proc")
            start2=$(java_process_start "$pid")
            [ "$start1" = "$start2" ] || verify_problem="采集期间进程已退出或身份发生变化"
            emit_finding "pid:$pid" "process" "unknown" "$verify_problem" "unknown" "$verify_problem" \
                "$(cpu_assess "$arch" "$CPU_STATE")" "$version" "$root_disp" "$vendor" "$product" "$vm" "$arch" \
                "" "false" "$container" "$NOTES"
            continue
        fi

        # --- 缓解参数 ---
        flags=""
        if [ "$named" -eq 1 ] || [ "$has_jvm" -eq 1 ]; then
            flags=$(launcher_flags "$proc/cmdline")
        fi
        feff="false"
        if [ -n "$flags" ]; then
            add_note "启动参数: ${flags}（启动证据，未确认该 JVM 的有效值）"
        fi
        container=$(container_hint "$proc")

        java_package_json= java_package_applies=false
        if [[ $verified == 1 && -n $host_mount && -n $host_root &&
              $(readlink "$proc/ns/mnt" 2>/dev/null) == "$host_mount" &&
              $(file_id "$proc/root") == "$host_root" ]]; then
            java_package_evidence "$libpath" "$st" "$version"
        fi

        # --- 采集期间身份是否变化 ---
        start2=$(java_process_start "$pid")
        libmeta3=$(libjvm_meta "$proc")
        if [ -z "$start1" ] || [ "$start1" != "$start2" ] || [ ! -d "$proc" ] ||
           { [[ -n $java_package_json ]] &&
             [[ $(readlink "$proc/ns/mnt" 2>/dev/null) != "$host_mount" || $(file_id "$proc/root") != "$host_root" ]]; } ||
           [ "$libmeta3" != "$libmeta" ] || [ "$(file_id "$proc/root$libpath")" != "$st" ] ||
           { [ "$identity_source" = map_files ] && [ "$(file_id "$proc/map_files/$range")" != "$st" ]; }; then
            emit_finding "pid:$pid" "process" "unknown" "采集期间进程已退出或身份发生变化。" \
                "unknown" "进程已退出" "$(cpu_assess "$arch" "$CPU_STATE")" "" "" "" "" "" "$arch" "" "false" "" ""
            continue
        fi

        if [ "$verified" -eq 1 ]; then
            printf '%s\n' "$st" >> "$ACTIVE_FILE"
        fi

        cpu=$(cpu_assess "$arch" "$CPU_STATE")
        bevid_and_build=$(assess_jdk_build "$root" "$version" "$vendor" "$product" "$vm" "$release_data")
        build=$(printf '%s' "$bevid_and_build" | cut -f1)
        bevid=$(printf '%s' "$bevid_and_build" | cut -f2-)
        [ -n "$build" ] || build="unknown"
        if [[ $java_package_applies == true && $product != *GraalVM* && ( $build == unknown || $build == candidate ) ]]; then
            build=fixed
            bevid="本机软件包公告与已核实的运行库构建一致"
        fi

        vmtext=$(lower "${vm:-} ${vmname:-}")
        case $vmtext in *openj9*) openj9=1 ;; *) openj9=0 ;; esac

        fn=0
        mit=0
        identity_confidence=strong
        [ "$weak_identity" -eq 0 ] || identity_confidence=weak
        disk_hint_version="" disk_hint_vendor="" disk_hint_product="" disk_hint_build=""
        if [ "$weak_identity" -eq 1 ]; then
            disk_hint_version=$disk_version
            disk_hint_vendor=$vendor
            disk_hint_product=$product
            disk_hint_build=$build
        fi

        if [ "$weak_identity" -eq 1 ]; then
            status=potential
            reason="运行库身份未核实：inode 相同、设备号不同，磁盘构建仅供参考"
            if [ "$disk_hint_build" = unfixed ]; then
                reason="$reason；发现受影响的磁盘构建"
            fi
            build=candidate
            bevid=$reason
            version=$disk_hint_version
            vendor=$disk_hint_vendor
            product=$disk_hint_product
            vm=""
        elif [ "$openj9" -eq 1 ]; then
            build="outside_scope"
            bevid="运行在 Eclipse OpenJ9（自有 Base64 实现，不经过 HotSpot intrinsic）"
            status="not_affected"
            reason="OpenJ9 不使用 HotSpot 的 Base64 intrinsic，不在本次影响面"
            add_note "OpenJ9 走自有实现；公告未单列该实现，若厂商有相反说明以厂商为准"
        else
            status=$(classify "$build" "$cpu" "$mit" "$fn" "$(norm_arch "$arch")")
            reason=$(make_reason "$status" "$build" "$bevid" "$cpu" "$mit" "$(norm_arch "$arch")")
        fi

        emit_finding "pid:$pid" "process" "$status" "$reason" "$build" "$bevid" \
            "$cpu" "$version" "$root_disp" "$vendor" "$product" "$vm" "$arch" \
            "$flags" "$feff" "$container" "$NOTES" \
            "$identity_confidence" "$disk_hint_version" "$disk_hint_vendor" "$disk_hint_product" "$disk_hint_build" "$java_package_json"
    done < <(
        web_process_paths | while IFS= read -r proc; do printf '%s\n' "${proc#/proc/}"; done
    )
}

# 非 Linux 平台：仅能做启动器级别的线索（Go 版在 macOS 上同样不校验运行库）
scan_processes_other() {
    local release_data pid exe root notes version vendor product vm arch cpu build bevid status reason bevid_and_build
    local scanned=0 process_list
        if ! process_list=$(
            ps -axww -o pid=,comm= 2>/dev/null | head -n "$((PROCESS_SCAN_LIMIT + 1))"
            statuses=("${PIPESTATUS[@]}")
            [[ ${statuses[1]} == 0 && ( ${statuses[0]} == 0 || ${statuses[0]} == 141 ) ]]
        ); then
            PROCESS_VISIBILITY_LIMITED=true
            warn "无法列出进程，运行中 JVM 的覆盖不完整。"
        fi
    while read -r pid exe; do
        [ -n "$pid" ] || continue
        if (( scanned >= PROCESS_SCAN_LIMIT )); then PROCESS_LIMIT_REACHED=true; break; fi
        scanned=$((scanned + 1))
        if [ -z "$exe" ] || ! java_name "$exe"; then
            continue
        fi
        NOTES=""
        root=$(java_root_of "$exe")
        version=""; vendor=""; vm=""; arch=""
        if release_data=$(release_snapshot "$root/release"); then
            version=$(release_value "$release_data" JAVA_RUNTIME_VERSION)
            [ -n "$version" ] || version=$(release_value "$release_data" JAVA_VERSION)
            vendor=$(release_value "$release_data" IMPLEMENTOR)
            vm=$(release_value "$release_data" JVM_VARIANT)
            arch=$(release_value "$release_data" OS_ARCH)
            add_note "运行中加载的库未核实，版本取磁盘启动器"
        else
            add_note "无 release 元数据"
        fi
        [ -n "$arch" ] || arch=$ARCH_RAW
        cpu=$(cpu_assess "$arch" "$CPU_STATE")
        product=$(jdk_product "$root" "$vendor" "$release_data")
        bevid_and_build=$(assess_jdk_build "$root" "$version" "$vendor" "$product" "$vm" "$release_data")
        build=$(printf '%s' "$bevid_and_build" | cut -f1)
        bevid=$(printf '%s' "$bevid_and_build" | cut -f2-)
        [ -n "$build" ] || build="unknown"
        status=$(classify "$build" "$cpu" 0 0 "$(norm_arch "$arch")" installation)
        reason=$(make_reason "$status" "$build" "$bevid" "$cpu" 0 "$(norm_arch "$arch")")
        emit_finding "pid:$pid" "process" "$status" "$reason" "$build" "$bevid" \
            "$cpu" "$version" "$root" "$vendor" "$product" "$vm" "$arch" "" "false" "" "$NOTES"
    done <<< "$process_list"
}

